  ('PB-T1-green', 1, 'PORTFOLIO-GAP', 'portfolio-gap-orphan', 'sql', 'SELECT x.id AS issue_id, ''portfolio-gap'' AS subject, json_object(''gap_rows'', (SELECT COUNT(*) FROM portfolio_gaps g WHERE g.issue_id = x.id), ''gap_open'', (SELECT COUNT(*) FROM portfolio_gaps g WHERE g.issue_id = x.id AND g.status = ''open''), ''own_contract'', COALESCE((SELECT c.status FROM remediation_contracts c WHERE c.class = ''issue-'' || x.id), ''none'')) AS facts_json FROM (SELECT a.id AS id FROM agent_issues a WHERE a.title LIKE ''PORTFOLIO-GAP %'' AND a.status = ''open'' AND a.title NOT LIKE ''PROBE-NEEDED-1: issue-%'' AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'',''monitoring'',''escalated'') AND c.class NOT LIKE ''%-BACKFILL-1'' AND instr(lower(c.verify_probe), ''close_evidence'') = 0) AND EXISTS (SELECT 1 FROM portfolio_gaps g WHERE g.issue_id = a.id)) x WHERE 1 = 1 AND ((SELECT COUNT(*) FROM portfolio_gaps g WHERE g.issue_id = x.id AND g.status = ''open'') = 0)', json_array('UPDATE remediation_contracts SET verify_probe = ''SELECT ''''resolved'''' AS expected, CASE WHEN (SELECT COUNT(*) FROM portfolio_gaps WHERE issue_id = '' || CAST(?1 AS INTEGER) || '') = 0 THEN ''''pending: no gap row carries issue '' || CAST(?1 AS INTEGER) || '''''' WHEN (SELECT COUNT(*) FROM portfolio_gaps WHERE issue_id = '' || CAST(?1 AS INTEGER) || '' AND status = ''''open'''') = 0 THEN ''''resolved'''' ELSE ''''pending: '''' || (SELECT COUNT(*) FROM portfolio_gaps WHERE issue_id = '' || CAST(?1 AS INTEGER) || '' AND status = ''''open'''') || '''' of '''' || (SELECT COUNT(*) FROM portfolio_gaps WHERE issue_id = '' || CAST(?1 AS INTEGER) || '') || '''' gap rows still open'''' END AS observed'', verify_transport = ''d1-query'', status = ''holding'', module = ''probe-template-v4-portfolio-gap'', last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime(''now''), expected_cadence_h = 1, precondition = ''PROBE-PLAYBOOKS-1 template portfolio-gap: the portfolio_gaps rows that carry this issue are its definition of done'', action = ''the portfolio autopilot closes the gap rows (portfolio_gaps.status open to closed or resolved), the probe reads them and a pass closes the issue'' WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND (status IN (''superseded'',''probe-review-refused'',''needs-machine-probe'') OR (status IN (''active'',''holding'',''monitoring'',''escalated'') AND instr(lower(verify_probe), ''close_evidence'') > 0)) AND EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = ?1 AND a.title LIKE ''PORTFOLIO-GAP %'' AND a.status = ''open'' AND a.title NOT LIKE ''PROBE-NEEDED-1: issue-%'' AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'',''monitoring'',''escalated'') AND c.class NOT LIKE ''%-BACKFILL-1'' AND instr(lower(c.verify_probe), ''close_evidence'') = 0) AND EXISTS (SELECT 1 FROM portfolio_gaps g WHERE g.issue_id = a.id) AND 1 = 1 AND ((SELECT COUNT(*) FROM portfolio_gaps g WHERE g.issue_id = a.id AND g.status = ''open'') = 0))', 'UPDATE remediation_contracts SET next_due_at = datetime(''now'',''+60 minutes'') WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND module = ''probe-template-v4-portfolio-gap'' AND status = ''holding'' AND last_verdict IS NULL AND attempts = 0', 'UPDATE remediation_contracts SET status = ''superseded'', last_verdict = ''superseded:circular-backfill-replaced'', next_due_at = NULL WHERE issue_id = ?1 AND class LIKE ''%-BACKFILL-1'' AND status IN (''active'',''holding'',''probe-review-refused'',''needs-machine-probe'') AND EXISTS (SELECT 1 FROM remediation_contracts n WHERE n.class = ''issue-'' || CAST(?1 AS INTEGER) AND n.module = ''probe-template-v4-portfolio-gap'' AND n.status IN (''active'',''holding''))'), json_array('UPDATE remediation_contracts SET status = ''superseded'', module = ''probe-template-v3-generic'', last_verdict = ''superseded:closure-observing-probe-at-birth (installed by breach-doctor rule PB-T1-green, then reverted)'', next_due_at = NULL WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND module = ''probe-template-v4-portfolio-gap''', 'UPDATE remediation_contracts SET status = ''active'', last_verdict = NULL, next_due_at = datetime(''now'') WHERE issue_id = ?1 AND class LIKE ''%-BACKFILL-1'' AND last_verdict = ''superseded:circular-backfill-replaced'''), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status = ''open'') THEN ''ok'' WHEN EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = ''issue-'' || CAST(?1 AS INTEGER) AND c.module = ''probe-template-v4-portfolio-gap'' AND c.status IN (''active'',''holding'')) THEN ''ok'' ELSE ''no-live-template'' END AS observed', 'delegated', 6, 30, 1, 'on', 'PORTFOLIO-GAP issue with no live closing path (its birth contract was superseded as circular, a BACKFILL-1 alias or a refused probe): install template T1 on its own contract, the probe reads the portfolio_gaps rows that carry the issue (portfolio_gaps.issue_id) and is ok when none is still open, and supersede a BACKFILL-1 alias only after the template is live (R7). Template text tested read-only on live qnfo-audit (issue 100341: pending 7 of 7 gap rows still open). Green-at-birth form (R8): every gap row that carries the issue is already closed or resolved, so the probe would read ok at install, so the contract is installed holding with its first executor read 60 minutes later, which is the second read before the autoclose trigger closes the issue (REMEDIATION-REOPEN-1 reopens a relapse). LIVE 2026-10-26 11:25Z: 0 hits.');

INSERT OR IGNORE INTO breach_playbooks (rule_id, version, family, cause_class, action_kind, trigger_sql, action_sql, revert_sql, verify_sql, min_ladder, max_per_tick, max_per_day, enabled, mode, note) VALUES
  ('PB-T3', 1, 'FLEET-JOURNEY-FAILED-1', 'journey-orphan', 'sql', 'WITH js AS MATERIALIZED (SELECT journey, ok, age_min FROM v_journey_state) SELECT x.id AS issue_id, ''journey'' AS subject, json_object(''journey'', x.t, ''runners'', (SELECT COUNT(*) FROM js s WHERE s.journey = x.t), ''failing_runners'', (SELECT COUNT(*) FROM js s WHERE s.journey = x.t AND s.ok = 0)) AS facts_json FROM (SELECT a.id AS id, substr(a.title, 25, instr(a.title, '' ('') - 25) AS t FROM agent_issues a WHERE a.title LIKE ''FLEET-JOURNEY-FAILED-1: %'' AND a.status = ''open'' AND a.title NOT LIKE ''PROBE-NEEDED-1: issue-%'' AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'',''monitoring'',''escalated'') AND c.class NOT LIKE ''%-BACKFILL-1'' AND instr(lower(c.verify_probe), ''close_evidence'') = 0) AND instr(a.title, '' ('') > 25) x WHERE length(x.t) BETWEEN 2 AND 64 AND x.t NOT GLOB ''*[^a-z0-9_-]*'' AND EXISTS (SELECT 1 FROM js s WHERE s.journey = x.t) AND NOT (COALESCE((SELECT MIN(s.ok) FROM js s WHERE s.journey = x.t AND s.age_min <= 180), 0) = 1 AND (SELECT COUNT(*) FROM js s WHERE s.journey = x.t AND s.age_min > 180) = 0)', json_array('UPDATE remediation_contracts SET verify_probe = ''SELECT ''''ok'''' AS expected, CASE WHEN (SELECT COUNT(*) FROM v_journey_state WHERE journey = '''''' || (SELECT substr(jj.title, 25, instr(jj.title, '' ('') - 25) FROM agent_issues jj WHERE jj.id = CAST(?1 AS INTEGER)) || '''''') = 0 THEN ''''pending: no journey_state row'''' WHEN (SELECT MIN(ok) FROM v_journey_state WHERE journey = '''''' || (SELECT substr(jj.title, 25, instr(jj.title, '' ('') - 25) FROM agent_issues jj WHERE jj.id = CAST(?1 AS INTEGER)) || '''''' AND age_min <= 180) = 1 AND (SELECT COUNT(*) FROM v_journey_state WHERE journey = '''''' || (SELECT substr(jj.title, 25, instr(jj.title, '' ('') - 25) FROM agent_issues jj WHERE jj.id = CAST(?1 AS INTEGER)) || '''''' AND age_min > 180) = 0 THEN ''''ok'''' ELSE ''''pending: '''' || (SELECT group_concat(runner || '''' ok='''' || ok || '''' age_min='''' || CAST(age_min AS INT), '''', '''') FROM v_journey_state WHERE journey = '''''' || (SELECT substr(jj.title, 25, instr(jj.title, '' ('') - 25) FROM agent_issues jj WHERE jj.id = CAST(?1 AS INTEGER)) || '''''') END AS observed'', verify_transport = ''d1-query'', status = ''active'', module = ''probe-template-v4-journey'', last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime(''now''), expected_cadence_h = 1, precondition = ''PROBE-PLAYBOOKS-1 template journey: every runner of the failing journey reads ok and fresh'', action = ''the journey runners run the journey again (fleet-journeys), the probe reads v_journey_state and a pass closes the issue'' WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND (status IN (''superseded'',''probe-review-refused'',''needs-machine-probe'') OR (status IN (''active'',''holding'',''monitoring'',''escalated'') AND instr(lower(verify_probe), ''close_evidence'') > 0)) AND EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = ?1 AND a.title LIKE ''FLEET-JOURNEY-FAILED-1: %'' AND a.status = ''open'' AND a.title NOT LIKE ''PROBE-NEEDED-1: issue-%'' AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'',''monitoring'',''escalated'') AND c.class NOT LIKE ''%-BACKFILL-1'' AND instr(lower(c.verify_probe), ''close_evidence'') = 0) AND instr(a.title, '' ('') > 25 AND length((substr(a.title, 25, instr(a.title, '' ('') - 25))) BETWEEN 2 AND 64 AND (substr(a.title, 25, instr(a.title, '' ('') - 25)) NOT GLOB ''*[^a-z0-9_-]*'' AND EXISTS (SELECT 1 FROM v_journey_state s WHERE s.journey = (substr(a.title, 25, instr(a.title, '' ('') - 25))) AND NOT (COALESCE((SELECT MIN(s.ok) FROM v_journey_state s WHERE s.journey = (substr(a.title, 25, instr(a.title, '' ('') - 25)) AND s.age_min <= 180), 0) = 1 AND (SELECT COUNT(*) FROM v_journey_state s WHERE s.journey = (substr(a.title, 25, instr(a.title, '' ('') - 25)) AND s.age_min > 180) = 0))', 'UPDATE remediation_contracts SET status = ''superseded'', last_verdict = ''superseded:circular-backfill-replaced'', next_due_at = NULL WHERE issue_id = ?1 AND class LIKE ''%-BACKFILL-1'' AND status IN (''active'',''holding'',''probe-review-refused'',''needs-machine-probe'') AND EXISTS (SELECT 1 FROM remediation_contracts n WHERE n.class = ''issue-'' || CAST(?1 AS INTEGER) AND n.module = ''probe-template-v4-journey'' AND n.status IN (''active'',''holding''))'), json_array('UPDATE remediation_contracts SET status = ''superseded'', module = ''probe-template-v3-generic'', last_verdict = ''superseded:closure-observing-probe-at-birth (installed by breach-doctor rule PB-T3, then reverted)'', next_due_at = NULL WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND module = ''probe-template-v4-journey''', 'UPDATE remediation_contracts SET status = ''active'', last_verdict = NULL, next_due_at = datetime(''now'') WHERE issue_id = ?1 AND class LIKE ''%-BACKFILL-1'' AND last_verdict = ''superseded:circular-backfill-replaced'''), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status = ''open'') THEN ''ok'' WHEN EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = ''issue-'' || CAST(?1 AS INTEGER) AND c.module = ''probe-template-v4-journey'' AND c.status IN (''active'',''holding'')) THEN ''ok'' ELSE ''no-live-template'' END AS observed', 'delegated', 6, 30, 1, 'on', 'FLEET-JOURNEY-FAILED-1 issue with no live closing path: install template T3, the probe reads v_journey_state for the journey named in the title (validated: characters a-z 0-9 _ -, at most 64, present in v_journey_state) and is ok when every runner''s latest row is ok and no older than 180 minutes (the fleet journeys run hourly on the gha runner: that cadence plus the 120 minutes SLA-120M-1 allows a freshness check on a loop slower than 120 minutes; it is a freshness window, not a stuck-item threshold). Template text tested read-only on live qnfo-audit (binding-census: pending cf ok=0, gha ok=0). The trigger reads the view once in a MATERIALIZED CTE (the view costs about 8.7k rows a reference). Pending form: the probe reads pending now, so the contract is installed active and the executor reads it within the hour. LIVE 2026-10-26 11:25Z: 1 hit (FLEET-JOURNEY-FAILED-1 binding-census, issue 100166).');

INSERT OR IGNORE INTO breach_playbooks (rule_id, version, family, cause_class, action_kind, trigger_sql, action_sql, revert_sql, verify_sql, min_ladder, max_per_tick, max_per_day, enabled, mode, note) VALUES
  ('PB-T3-green', 1, 'FLEET-JOURNEY-FAILED-1', 'journey-orphan', 'sql', 'WITH js AS MATERIALIZED (SELECT journey, ok, age_min FROM v_journey_state) SELECT x.id AS issue_id, ''journey'' AS subject, json_object(''journey'', x.t, ''runners'', (SELECT COUNT(*) FROM js s WHERE s.journey = x.t), ''failing_runners'', (SELECT COUNT(*) FROM js s WHERE s.journey = x.t AND s.ok = 0)) AS facts_json FROM (SELECT a.id AS id, substr(a.title, 25, instr(a.title, '' ('') - 25) AS t FROM agent_issues a WHERE a.title LIKE ''FLEET-JOURNEY-FAILED-1: %'' AND a.status = ''open'' AND a.title NOT LIKE ''PROBE-NEEDED-1: issue-%'' AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'',''monitoring'',''escalated'') AND c.class NOT LIKE ''%-BACKFILL-1'' AND instr(lower(c.verify_probe), ''close_evidence'') = 0) AND instr(a.title, '' ('') > 25) x WHERE length(x.t) BETWEEN 2 AND 64 AND x.t NOT GLOB ''*[^a-z0-9_-]*'' AND EXISTS (SELECT 1 FROM js s WHERE s.journey = x.t) AND (COALESCE((SELECT MIN(s.ok) FROM js s WHERE s.journey = x.t AND s.age_min <= 180), 0) = 1 AND (SELECT COUNT(*) FROM js s WHERE s.journey = x.t AND s.age_min > 180) = 0)', json_array('UPDATE remediation_contracts SET verify_probe = ''SELECT ''''ok'''' AS expected, CASE WHEN (SELECT COUNT(*) FROM v_journey_state WHERE journey = '''''' || (SELECT substr(jj.title, 25, instr(jj.title, '' ('') - 25) FROM agent_issues jj WHERE jj.id = CAST(?1 AS INTEGER)) || '''''') = 0 THEN ''''pending: no journey_state row'''' WHEN (SELECT MIN(ok) FROM v_journey_state WHERE journey = '''''' || (SELECT substr(jj.title, 25, instr(jj.title, '' ('') - 25) FROM agent_issues jj WHERE jj.id = CAST(?1 AS INTEGER)) || '''''' AND age_min <= 180) = 1 AND (SELECT COUNT(*) FROM v_journey_state WHERE journey = '''''' || (SELECT substr(jj.title, 25, instr(jj.title, '' ('') - 25) FROM agent_issues jj WHERE jj.id = CAST(?1 AS INTEGER)) || '''''' AND age_min > 180) = 0 THEN ''''ok'''' ELSE ''''pending: '''' || (SELECT group_concat(runner || '''' ok='''' || ok || '''' age_min='''' || CAST(age_min AS INT), '''', '''') FROM v_journey_state WHERE journey = '''''' || (SELECT substr(jj.title, 25, instr(jj.title, '' ('') - 25) FROM agent_issues jj WHERE jj.id = CAST(?1 AS INTEGER)) || '''''') END AS observed'', verify_transport = ''d1-query'', status = ''holding'', module = ''probe-template-v4-journey'', last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime(''now''), expected_cadence_h = 1, precondition = ''PROBE-PLAYBOOKS-1 template journey: every runner of the failing journey reads ok and fresh'', action = ''the journey runners run the journey again (fleet-journeys), the probe reads v_journey_state and a pass closes the issue'' WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND (status IN (''superseded'',''probe-review-refused'',''needs-machine-probe'') OR (status IN (''active'',''holding'',''monitoring'',''escalated'') AND instr(lower(verify_probe), ''close_evidence'') > 0)) AND EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = ?1 AND a.title LIKE ''FLEET-JOURNEY-FAILED-1: %'' AND a.status = ''open'' AND a.title NOT LIKE ''PROBE-NEEDED-1: issue-%'' AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'',''monitoring'',''escalated'') AND c.class NOT LIKE ''%-BACKFILL-1'' AND instr(lower(c.verify_probe), ''close_evidence'') = 0) AND instr(a.title, '' ('') > 25 AND length((substr(a.title, 25, instr(a.title, '' ('') - 25))) BETWEEN 2 AND 64 AND (substr(a.title, 25, instr(a.title, '' ('') - 25)) NOT GLOB ''*[^a-z0-9_-]*'' AND EXISTS (SELECT 1 FROM v_journey_state s WHERE s.journey = (substr(a.title, 25, instr(a.title, '' ('') - 25))) AND (COALESCE((SELECT MIN(s.ok) FROM v_journey_state s WHERE s.journey = (substr(a.title, 25, instr(a.title, '' ('') - 25)) AND s.age_min <= 180), 0) = 1 AND (SELECT COUNT(*) FROM v_journey_state s WHERE s.journey = (substr(a.title, 25, instr(a.title, '' ('') - 25)) AND s.age_min > 180) = 0))', 'UPDATE remediation_contracts SET next_due_at = datetime(''now'',''+60 minutes'') WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND module = ''probe-template-v4-journey'' AND status = ''holding'' AND last_verdict IS NULL AND attempts = 0', 'UPDATE remediation_contracts SET status = ''superseded'', last_verdict = ''superseded:circular-backfill-replaced'', next_due_at = NULL WHERE issue_id = ?1 AND class LIKE ''%-BACKFILL-1'' AND status IN (''active'',''holding'',''probe-review-refused'',''needs-machine-probe'') AND EXISTS (SELECT 1 FROM remediation_contracts n WHERE n.class = ''issue-'' || CAST(?1 AS INTEGER) AND n.module = ''probe-template-v4-journey'' AND n.status IN (''active'',''holding''))'), json_array('UPDATE remediation_contracts SET status = ''superseded'', module = ''probe-template-v3-generic'', last_verdict = ''superseded:closure-observing-probe-at-birth (installed by breach-doctor rule PB-T3-green, then reverted)'', next_due_at = NULL WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND module = ''probe-template-v4-journey''', 'UPDATE remediation_contracts SET status = ''active'', last_verdict = NULL, next_due_at = datetime(''now'') WHERE issue_id = ?1 AND class LIKE ''%-BACKFILL-1'' AND last_verdict = ''superseded:circular-backfill-replaced'''), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status = ''open'') THEN ''ok'' WHEN EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = ''issue-'' || CAST(?1 AS INTEGER) AND c.module = ''probe-template-v4-journey'' AND c.status IN (''active'',''holding'')) THEN ''ok'' ELSE ''no-live-template'' END AS observed', 'delegated', 6, 30, 1, 'on', 'FLEET-JOURNEY-FAILED-1 issue with no live closing path: install template T3, the probe reads v_journey_state for the journey named in the title (validated: characters a-z 0-9 _ -, at most 64, present in v_journey_state) and is ok when every runner''s latest row is ok and no older than 180 minutes (the fleet journeys run hourly on the gha runner: that cadence plus the 120 minutes SLA-120M-1 allows a freshness check on a loop slower than 120 minutes; it is a freshness window, not a stuck-item threshold). Template text tested read-only on live qnfo-audit (binding-census: pending cf ok=0, gha ok=0). The trigger reads the view once in a MATERIALIZED CTE (the view costs about 8.7k rows a reference). Green-at-birth form (R8): every runner of the journey already reads ok and fresh, so the probe would read ok at install, so the contract is installed holding with its first executor read 60 minutes later (the second read before the autoclose trigger closes it). LIVE 2026-10-26 11:25Z: 0 hits.');

INSERT OR IGNORE INTO breach_playbooks (rule_id, version, family, cause_class, action_kind, trigger_sql, action_sql, revert_sql, verify_sql, min_ladder, max_per_tick, max_per_day, enabled, mode, note) VALUES
  ('PB-T4', 1, 'METRIC-TRIGGER', 'metric-orphan', 'sql', 'WITH ts AS MATERIALIZED (SELECT id, metric_key, hit, val FROM v_metric_trigger_state) SELECT x.id AS issue_id, ''metric'' AS subject, json_object(''metric'', x.t, ''trigger_hit'', (SELECT s.hit FROM ts s WHERE s.metric_key = x.t ORDER BY s.id LIMIT 1), ''trigger_val'', (SELECT s.val FROM ts s WHERE s.metric_key = x.t ORDER BY s.id LIMIT 1)) AS facts_json FROM (SELECT a.id AS id, CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END AS t FROM agent_issues a WHERE (a.title LIKE ''METRIC-TRIGGER-%'' OR a.title GLOB ''[a-z]*'') AND a.status = ''open'' AND a.title NOT LIKE ''PROBE-NEEDED-1: issue-%'' AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'',''monitoring'',''escalated'') AND c.class NOT LIKE ''%-BACKFILL-1'' AND instr(lower(c.verify_probe), ''close_evidence'') = 0) AND (a.title LIKE ''METRIC-TRIGGER-%'' OR EXISTS (SELECT 1 FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%''))))) x WHERE x.t IS NOT NULL AND length(x.t) BETWEEN 2 AND 64 AND x.t NOT GLOB ''*[^a-z0-9_]*'' AND EXISTS (SELECT 1 FROM ts s WHERE s.metric_key = x.t) AND NOT (COALESCE((SELECT s.hit FROM ts s WHERE s.metric_key = x.t ORDER BY s.id LIMIT 1), 1) = 0 AND (SELECT s.val FROM ts s WHERE s.metric_key = x.t ORDER BY s.id LIMIT 1) IS NOT NULL)', json_array('UPDATE remediation_contracts SET verify_probe = ''SELECT ''''ok'''' AS expected, CASE WHEN (SELECT hit FROM v_metric_trigger_state WHERE metric_key = '''''' || (SELECT CASE WHEN mm.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(mm.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE mm.title = m.metric OR (length(m.metric) <= 45 AND (mm.title LIKE m.metric || '' %'' OR mm.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END FROM agent_issues mm WHERE mm.id = CAST(?1 AS INTEGER)) || '''''' ORDER BY id LIMIT 1) = 0 AND (SELECT val FROM v_metric_trigger_state WHERE metric_key = '''''' || (SELECT CASE WHEN mm.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(mm.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE mm.title = m.metric OR (length(m.metric) <= 45 AND (mm.title LIKE m.metric || '' %'' OR mm.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END FROM agent_issues mm WHERE mm.id = CAST(?1 AS INTEGER)) || '''''' ORDER BY id LIMIT 1) IS NOT NULL THEN ''''ok'''' ELSE ''''pending: '''' || COALESCE((SELECT ''''val='''' || val || '''' '''' || operator || '''' '''' || threshold FROM v_metric_trigger_state WHERE metric_key = '''''' || (SELECT CASE WHEN mm.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(mm.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE mm.title = m.metric OR (length(m.metric) <= 45 AND (mm.title LIKE m.metric || '' %'' OR mm.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END FROM agent_issues mm WHERE mm.id = CAST(?1 AS INTEGER)) || '''''' ORDER BY id LIMIT 1), ''''no trigger for metric'''') END AS observed'', verify_transport = ''d1-query'', status = ''active'', module = ''probe-template-v4-metric'', last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime(''now''), expected_cadence_h = 1, precondition = ''PROBE-PLAYBOOKS-1 template metric: the trigger of the metric the issue is about no longer hits'', action = ''the owner loop of the metric fixes its cause, the probe reads v_metric_trigger_state and a pass closes the issue'' WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND (status IN (''superseded'',''probe-review-refused'',''needs-machine-probe'') OR (status IN (''active'',''holding'',''monitoring'',''escalated'') AND instr(lower(verify_probe), ''close_evidence'') > 0)) AND EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = ?1 AND (a.title LIKE ''METRIC-TRIGGER-%'' OR a.title GLOB ''[a-z]*'') AND a.status = ''open'' AND a.title NOT LIKE ''PROBE-NEEDED-1: issue-%'' AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'',''monitoring'',''escalated'') AND c.class NOT LIKE ''%-BACKFILL-1'' AND instr(lower(c.verify_probe), ''close_evidence'') = 0) AND (a.title LIKE ''METRIC-TRIGGER-%'' OR EXISTS (SELECT 1 FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')))) AND (CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END) IS NOT NULL AND length((CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END)) BETWEEN 2 AND 64 AND (CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END) NOT GLOB ''*[^a-z0-9_]*'' AND EXISTS (SELECT 1 FROM v_metric_trigger_state s WHERE s.metric_key = (CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END)) AND NOT (COALESCE((SELECT s.hit FROM v_metric_trigger_state s WHERE s.metric_key = (CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END) ORDER BY s.id LIMIT 1), 1) = 0 AND (SELECT s.val FROM v_metric_trigger_state s WHERE s.metric_key = (CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END) ORDER BY s.id LIMIT 1) IS NOT NULL))', 'UPDATE remediation_contracts SET status = ''superseded'', last_verdict = ''superseded:circular-backfill-replaced'', next_due_at = NULL WHERE issue_id = ?1 AND class LIKE ''%-BACKFILL-1'' AND status IN (''active'',''holding'',''probe-review-refused'',''needs-machine-probe'') AND EXISTS (SELECT 1 FROM remediation_contracts n WHERE n.class = ''issue-'' || CAST(?1 AS INTEGER) AND n.module = ''probe-template-v4-metric'' AND n.status IN (''active'',''holding''))'), json_array('UPDATE remediation_contracts SET status = ''superseded'', module = ''probe-template-v3-generic'', last_verdict = ''superseded:closure-observing-probe-at-birth (installed by breach-doctor rule PB-T4, then reverted)'', next_due_at = NULL WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND module = ''probe-template-v4-metric''', 'UPDATE remediation_contracts SET status = ''active'', last_verdict = NULL, next_due_at = datetime(''now'') WHERE issue_id = ?1 AND class LIKE ''%-BACKFILL-1'' AND last_verdict = ''superseded:circular-backfill-replaced'''), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status = ''open'') THEN ''ok'' WHEN EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = ''issue-'' || CAST(?1 AS INTEGER) AND c.module = ''probe-template-v4-metric'' AND c.status IN (''active'',''holding'')) THEN ''ok'' ELSE ''no-live-template'' END AS observed', 'delegated', 6, 30, 1, 'on', 'Issue about a registered metric (its title starts with a metric_registry key, or is METRIC-TRIGGER-<trigger id>) with no live closing path: install template T4, the probe reads v_metric_trigger_state for that metric (validated: characters a-z 0-9 _, at most 64, present in the view) and is ok when its trigger does not hit and has a value. Template text tested read-only on live qnfo-audit (content_items_over_stage_sla: pending val=2231.0 gt 0.0, trigger 786: val 3 lt 5, hit 1). The trigger filters on a lower-case first letter before it scans metric_registry, reads the view once in a MATERIALIZED CTE and never uses a registry key longer than 45 characters as a LIKE pattern (D1 refuses a pattern over 50 bytes). Pending form: the probe reads pending now, so the contract is installed active and the executor reads it within the hour. LIVE 2026-10-26 11:25Z: 2 hits (human_wait_oldest_min issue 1000000: val 8916 gt 120, METRIC-TRIGGER-786 issue 1893: val 4 lt 5). A third (issues_unaccounted, 1000034) was given a live contract by another loop between the 10:55Z and 11:25Z reads. BELIEF: both T4 rows act on the belief that a title starting with a metric key is about that metric (belief_registry pb-t4-metric-title-is-about-the-metric, falsified by belief-pb-t4-metric-title-is-about-the-metric: an issue carrying this template that is reopened).');

INSERT OR IGNORE INTO breach_playbooks (rule_id, version, family, cause_class, action_kind, trigger_sql, action_sql, revert_sql, verify_sql, min_ladder, max_per_tick, max_per_day, enabled, mode, note) VALUES
  ('PB-T4-green', 1, 'METRIC-TRIGGER', 'metric-orphan', 'sql', 'WITH ts AS MATERIALIZED (SELECT id, metric_key, hit, val FROM v_metric_trigger_state) SELECT x.id AS issue_id, ''metric'' AS subject, json_object(''metric'', x.t, ''trigger_hit'', (SELECT s.hit FROM ts s WHERE s.metric_key = x.t ORDER BY s.id LIMIT 1), ''trigger_val'', (SELECT s.val FROM ts s WHERE s.metric_key = x.t ORDER BY s.id LIMIT 1)) AS facts_json FROM (SELECT a.id AS id, CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END AS t FROM agent_issues a WHERE (a.title LIKE ''METRIC-TRIGGER-%'' OR a.title GLOB ''[a-z]*'') AND a.status = ''open'' AND a.title NOT LIKE ''PROBE-NEEDED-1: issue-%'' AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'',''monitoring'',''escalated'') AND c.class NOT LIKE ''%-BACKFILL-1'' AND instr(lower(c.verify_probe), ''close_evidence'') = 0) AND (a.title LIKE ''METRIC-TRIGGER-%'' OR EXISTS (SELECT 1 FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%''))))) x WHERE x.t IS NOT NULL AND length(x.t) BETWEEN 2 AND 64 AND x.t NOT GLOB ''*[^a-z0-9_]*'' AND EXISTS (SELECT 1 FROM ts s WHERE s.metric_key = x.t) AND (COALESCE((SELECT s.hit FROM ts s WHERE s.metric_key = x.t ORDER BY s.id LIMIT 1), 1) = 0 AND (SELECT s.val FROM ts s WHERE s.metric_key = x.t ORDER BY s.id LIMIT 1) IS NOT NULL)', json_array('UPDATE remediation_contracts SET verify_probe = ''SELECT ''''ok'''' AS expected, CASE WHEN (SELECT hit FROM v_metric_trigger_state WHERE metric_key = '''''' || (SELECT CASE WHEN mm.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(mm.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE mm.title = m.metric OR (length(m.metric) <= 45 AND (mm.title LIKE m.metric || '' %'' OR mm.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END FROM agent_issues mm WHERE mm.id = CAST(?1 AS INTEGER)) || '''''' ORDER BY id LIMIT 1) = 0 AND (SELECT val FROM v_metric_trigger_state WHERE metric_key = '''''' || (SELECT CASE WHEN mm.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(mm.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE mm.title = m.metric OR (length(m.metric) <= 45 AND (mm.title LIKE m.metric || '' %'' OR mm.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END FROM agent_issues mm WHERE mm.id = CAST(?1 AS INTEGER)) || '''''' ORDER BY id LIMIT 1) IS NOT NULL THEN ''''ok'''' ELSE ''''pending: '''' || COALESCE((SELECT ''''val='''' || val || '''' '''' || operator || '''' '''' || threshold FROM v_metric_trigger_state WHERE metric_key = '''''' || (SELECT CASE WHEN mm.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(mm.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE mm.title = m.metric OR (length(m.metric) <= 45 AND (mm.title LIKE m.metric || '' %'' OR mm.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END FROM agent_issues mm WHERE mm.id = CAST(?1 AS INTEGER)) || '''''' ORDER BY id LIMIT 1), ''''no trigger for metric'''') END AS observed'', verify_transport = ''d1-query'', status = ''holding'', module = ''probe-template-v4-metric'', last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime(''now''), expected_cadence_h = 1, precondition = ''PROBE-PLAYBOOKS-1 template metric: the trigger of the metric the issue is about no longer hits'', action = ''the owner loop of the metric fixes its cause, the probe reads v_metric_trigger_state and a pass closes the issue'' WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND (status IN (''superseded'',''probe-review-refused'',''needs-machine-probe'') OR (status IN (''active'',''holding'',''monitoring'',''escalated'') AND instr(lower(verify_probe), ''close_evidence'') > 0)) AND EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = ?1 AND (a.title LIKE ''METRIC-TRIGGER-%'' OR a.title GLOB ''[a-z]*'') AND a.status = ''open'' AND a.title NOT LIKE ''PROBE-NEEDED-1: issue-%'' AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'',''monitoring'',''escalated'') AND c.class NOT LIKE ''%-BACKFILL-1'' AND instr(lower(c.verify_probe), ''close_evidence'') = 0) AND (a.title LIKE ''METRIC-TRIGGER-%'' OR EXISTS (SELECT 1 FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')))) AND (CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END) IS NOT NULL AND length((CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END)) BETWEEN 2 AND 64 AND (CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END) NOT GLOB ''*[^a-z0-9_]*'' AND EXISTS (SELECT 1 FROM v_metric_trigger_state s WHERE s.metric_key = (CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END)) AND (COALESCE((SELECT s.hit FROM v_metric_trigger_state s WHERE s.metric_key = (CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END) ORDER BY s.id LIMIT 1), 1) = 0 AND (SELECT s.val FROM v_metric_trigger_state s WHERE s.metric_key = (CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN (SELECT mt.metric_key FROM analytics_metric_triggers mt WHERE mt.id = CAST(substr(a.title, 16) AS INTEGER)) ELSE (SELECT m.metric FROM metric_registry m WHERE a.title = m.metric OR (length(m.metric) <= 45 AND (a.title LIKE m.metric || '' %'' OR a.title LIKE m.metric || '':%'')) ORDER BY length(m.metric) DESC LIMIT 1) END) ORDER BY s.id LIMIT 1) IS NOT NULL))', 'UPDATE remediation_contracts SET next_due_at = datetime(''now'',''+60 minutes'') WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND module = ''probe-template-v4-metric'' AND status = ''holding'' AND last_verdict IS NULL AND attempts = 0', 'UPDATE remediation_contracts SET status = ''superseded'', last_verdict = ''superseded:circular-backfill-replaced'', next_due_at = NULL WHERE issue_id = ?1 AND class LIKE ''%-BACKFILL-1'' AND status IN (''active'',''holding'',''probe-review-refused'',''needs-machine-probe'') AND EXISTS (SELECT 1 FROM remediation_contracts n WHERE n.class = ''issue-'' || CAST(?1 AS INTEGER) AND n.module = ''probe-template-v4-metric'' AND n.status IN (''active'',''holding''))'), json_array('UPDATE remediation_contracts SET status = ''superseded'', module = ''probe-template-v3-generic'', last_verdict = ''superseded:closure-observing-probe-at-birth (installed by breach-doctor rule PB-T4-green, then reverted)'', next_due_at = NULL WHERE issue_id = ?1 AND class = ''issue-'' || CAST(?1 AS INTEGER) AND module = ''probe-template-v4-metric''', 'UPDATE remediation_contracts SET status = ''active'', last_verdict = NULL, next_due_at = datetime(''now'') WHERE issue_id = ?1 AND class LIKE ''%-BACKFILL-1'' AND last_verdict = ''superseded:circular-backfill-replaced'''), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status = ''open'') THEN ''ok'' WHEN EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = ''issue-'' || CAST(?1 AS INTEGER) AND c.module = ''probe-template-v4-metric'' AND c.status IN (''active'',''holding'')) THEN ''ok'' ELSE ''no-live-template'' END AS observed', 'delegated', 6, 30, 1, 'on', 'Issue about a registered metric (its title starts with a metric_registry key, or is METRIC-TRIGGER-<trigger id>) with no live closing path: install template T4, the probe reads v_metric_trigger_state for that metric (validated: characters a-z 0-9 _, at most 64, present in the view) and is ok when its trigger does not hit and has a value. Template text tested read-only on live qnfo-audit (content_items_over_stage_sla: pending val=2231.0 gt 0.0, trigger 786: val 3 lt 5, hit 1). The trigger filters on a lower-case first letter before it scans metric_registry, reads the view once in a MATERIALIZED CTE and never uses a registry key longer than 45 characters as a LIKE pattern (D1 refuses a pattern over 50 bytes). Green-at-birth form (R8): the metric''s trigger already reads hit 0 with a value, so the probe would read ok at install, so the contract is installed holding with its first executor read 60 minutes later (the second read before the autoclose trigger closes it). LIVE 2026-10-26 11:25Z: 0 hits. BELIEF: see PB-T4 (belief-pb-t4-metric-title-is-about-the-metric).');

