INSERT OR IGNORE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('probe-playbooks-metrics', 'PROBE-PLAYBOOKS-1 metric observer', 'workflow', json_object('steps', json_array(json_object('name', 'orphan_issues_no_live_path', 'type', 'sql', 'db', 'AUDIT', 'sql', 'UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM agent_issues a WHERE a.status = ''open'' AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' AND a.created_at <= (CAST(strftime(''%s'',''now'') AS INTEGER) - 3600) * 1000 AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'',''monitoring'',''escalated'') AND c.class NOT LIKE ''%-BACKFILL-1'' AND instr(lower(c.verify_probe), ''close_evidence'') = 0)) AS TEXT), last_refreshed = datetime(''now''), state = ''MEASURED'' WHERE metric = ''orphan_issues_no_live_path'''), json_object('name', 'probe_author_accept_rate_7d', 'type', 'sql', 'db', 'AUDIT', 'sql', 'UPDATE metric_registry SET last_value = CAST((SELECT CASE WHEN s.a + s.r < 30 THEN 100 ELSE ROUND(100.0 * s.a / (s.a + s.r), 1) END FROM (SELECT (SELECT COUNT(*) FROM cloud_ops_events WHERE kind = ''remediation.probe-authored'' AND ts > strftime(''%Y-%m-%dT%H:%M:%fZ'',''now'',''-7 days'')) AS a, (SELECT COUNT(*) FROM cloud_ops_events WHERE kind = ''remediation.probe-author-reject'' AND ts > strftime(''%Y-%m-%dT%H:%M:%fZ'',''now'',''-7 days'')) AS r) s) AS TEXT), last_refreshed = datetime(''now''), state = ''MEASURED'' WHERE metric = ''probe_author_accept_rate_7d'''), json_object('name', 'pn_open_over_120m', 'type', 'sql', 'db', 'AUDIT', 'sql', 'UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM agent_issues WHERE status = ''open'' AND title LIKE ''PROBE-NEEDED-1: issue-%'' AND created_at <= (CAST(strftime(''%s'',''now'') AS INTEGER) - 7200) * 1000) AS TEXT), last_refreshed = datetime(''now''), state = ''MEASURED'' WHERE metric = ''pn_open_over_120m'''))), 30000, 1, 1, 1, datetime('now'));

