UPDATE metric_registry SET last_value = CAST((SELECT CASE WHEN s.a + s.r < 30 THEN 100 ELSE ROUND(100.0 * s.a / (s.a + s.r), 1) END FROM (SELECT (SELECT COUNT(*) FROM cloud_ops_events WHERE kind = 'remediation.probe-authored' AND ts > strftime('%Y-%m-%dT%H:%M:%fZ','now','-7 days')) AS a, (SELECT COUNT(*) FROM cloud_ops_events WHERE kind = 'remediation.probe-author-reject' AND ts > strftime('%Y-%m-%dT%H:%M:%fZ','now','-7 days')) AS r) s) AS TEXT), last_refreshed = datetime('now'), state = 'MEASURED' WHERE metric = 'probe_author_accept_rate_7d' AND last_refreshed IS NULL;
UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM agent_issues WHERE status = 'open' AND title LIKE 'PROBE-NEEDED-1: issue-%' AND created_at <= (CAST(strftime('%s','now') AS INTEGER) - 7200) * 1000) AS TEXT), last_refreshed = datetime('now'), state = 'MEASURED' WHERE metric = 'pn_open_over_120m' AND last_refreshed IS NULL;

-- ---- failure modes and their detectors (ANTIFRAGILE-1: every failure mode found gets a row and an fm- detector)
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('probe-author-unreachable', 'the model probe author never runs: PROBE-NEEDED-1 issues are filed and no probe is authored or rejected',
  'rtEnsureLivePath called rtAuthorLivePathProbe without env, read the model from a binding the worker does not have and logged nothing, so remediation.probe-authored held 0 events against 77 PROBE-NEEDED-1 filings in 7 days (PROBE-AUTHOR-BINDING-1 fixed the binding in 0.49.2, and a regression would be silent again)',
  'the author records one remediation.probe-author-reject event per issue per hour for every rejection and one remediation.probe-authored event per accept: the detector requires one of them after the oldest PROBE-NEEDED-1 filing of the last 120 minutes; orphan issues with a known title shape get a template probe from the breach doctor without a model (PB-T rows)',
  'fm-probe-author-unreachable: a PROBE-NEEDED-1 issue was filed in the last 120 minutes and the author has no event since', 'fm-probe-author-unreachable', '2026-10-26', 1000266,
  'a remediation.probe-needed-filed event in the last 120 minutes and no remediation.probe-authored or remediation.probe-author-reject event since the oldest of them', 'PROBE-NEEDED-1 issues pile up (53 open on 2026-10-26) and orphan_issues_no_live_path stays above 0', 'every issue whose only closing path is a superseded contract'),
 ('pn-probe-refused-by-reviewer', 'the fleet''s own deterministic PROBE-NEEDED-1 probe is judged self-confirming by a model and leaves both executors',
  'qnfo-cloud-ops PROBE-REVIEW-1 judges every d1-query contract that is not module probe-template%, and a model that disagreed with itself on one template text refused 17 of 53',
  'breach playbook PN-R3 restores the contract with module probe-template-v4-pn, which PROBE-REVIEW-1 skips; fm-pn-probe-refused reads the refusals older than 120 minutes', 'fm-pn-probe-refused: no PROBE-NEEDED-1 issue older than 120 minutes keeps a refused contract', 'fm-pn-probe-refused', '2026-10-26', 1000266,
  'a PROBE-NEEDED-1 contract in status probe-review-refused', 'the PN issue stays open and nothing reads its probe', 'one PN issue per refusal'),
 ('pn-target-closed-open', 'a PROBE-NEEDED-1 issue stays open after the issue it asked a probe for was closed',
  'the PN contract was refused by PROBE-REVIEW-1 or never read, so its own probe never ran to autoclose the PN (5 PN stayed open 31 to 111 hours)',
  'breach playbook PN-R1 closes it with evidence 30 minutes after the target closed; ISSUE-HYGIENE-1 issue-meta-fold is the hourly path; fm-pn-target-closed-open reads the ones older than 60 minutes', 'fm-pn-target-closed-open: no open PROBE-NEEDED-1 issue with a target closed for 60 minutes', 'fm-pn-target-closed-open', '2026-10-26', 1000266,
  'a PROBE-NEEDED-1 issue open while its target is closed, resolved or wontfix for 60 minutes', 'pn_open_over_120m above 0 with nothing left to do', 'one PN issue per occurrence'),
 ('born-superseded-real-probe', 'a contract superseded at birth as circular holds a probe that measures a real condition, so the issue has no closing path',
  'CLOSE-PROBE-CIRCULAR-1 (contract_probe_templates_v3_generic) supersedes the birth contract of every issue whose source is not a live service, and a probe written for the contract later (METRIC-UNMEASURED-1 issues 1000384 to 1000389) kept the superseded status',
  'breach playbook PB-R0 restores it (status active) when the probe reads none of agent_issues, issue_triage, issue_lifecycle and carries no issue id; fm-born-superseded-real-probe reads the ones older than 120 minutes', 'fm-born-superseded-real-probe: no open issue older than 120 minutes with a superseded-at-birth contract and a real probe', 'fm-born-superseded-real-probe', '2026-10-26', 1000266,
  'an open issue with no active or holding contract and a superseded:closure-observing-probe-at-birth contract whose probe is not circular', 'orphan_issues_no_live_path above 0 for an issue that has a probe', 'one issue per occurrence');

-- the three PN detectors are first read after the playbooks have had their 30 minutes of measure and a tick to act (next_due_at), so the birth of this file is not itself a recurrence.
-- Every detector threshold is stated in minutes and none exceeds 120 (SLA-120M-1; 7200 s, was 10800): the doctor's age gate is 60 minutes, a case is applied on the next 10-minute tick and a failed case is retried after 60.
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, verify_probe, verify_transport, max_attempts, expected_cadence_h, status, precondition, action, escalate_to, module, next_due_at) VALUES
 ('fm-probe-author-unreachable', NULL, 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM cloud_ops_events WHERE kind = ''remediation.probe-needed-filed'' AND ts > strftime(''%Y-%m-%dT%H:%M:%fZ'',''now'',''-120 minutes'')) = 0 THEN ''ok'' WHEN (SELECT COUNT(*) FROM cloud_ops_events WHERE kind IN (''remediation.probe-authored'',''remediation.probe-author-reject'') AND ts >= (SELECT MIN(f.ts) FROM cloud_ops_events f WHERE f.kind = ''remediation.probe-needed-filed'' AND f.ts > strftime(''%Y-%m-%dT%H:%M:%fZ'',''now'',''-120 minutes''))) >= 1 THEN ''ok'' ELSE ''pending: '' || (SELECT COUNT(*) FROM cloud_ops_events WHERE kind = ''remediation.probe-needed-filed'' AND ts > strftime(''%Y-%m-%dT%H:%M:%fZ'',''now'',''-120 minutes'')) || '' probe-needed filings in 120 minutes and no author attempt since the first of them'' END AS observed', 'd1-query', 3, 1, 'active', 'PROBE-PLAYBOOKS-1', 'failure-mode detector', 'qnfo-fleet-control', 'failure-mode', datetime('now')),
 ('fm-pn-probe-refused', NULL, 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM remediation_contracts c JOIN agent_issues p ON p.id = c.issue_id WHERE p.status = ''open'' AND p.title LIKE ''PROBE-NEEDED-1: issue-%'' AND c.class = ''issue-'' || p.id AND c.status = ''probe-review-refused'' AND p.created_at <= (CAST(strftime(''%s'',''now'') AS INTEGER) - 7200) * 1000) AS TEXT) AS observed', 'd1-query', 3, 1, 'active', 'PROBE-PLAYBOOKS-1', 'failure-mode detector', 'qnfo-fleet-control', 'failure-mode', datetime('now', '+90 minutes')),
 ('fm-pn-target-closed-open', NULL, 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM agent_issues p JOIN agent_issues t ON t.id = CAST(substr(p.title, 23) AS INTEGER) WHERE p.status = ''open'' AND p.source = ''qnfo-fleet-control'' AND p.title LIKE ''PROBE-NEEDED-1: issue-%'' AND t.status IN (''closed'',''resolved'',''wontfix'') AND COALESCE((SELECT MAX(l.ts) FROM issue_lifecycle l WHERE l.issue_id = t.id AND l.to_status IN (''closed'',''resolved'',''wontfix'')), '''') <= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-60 minutes'')) AS TEXT) AS observed', 'd1-query', 3, 1, 'active', 'PROBE-PLAYBOOKS-1', 'failure-mode detector', 'qnfo-fleet-control', 'failure-mode', datetime('now', '+90 minutes')),
 ('fm-born-superseded-real-probe', NULL, 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM agent_issues a JOIN remediation_contracts c ON c.class = ''issue-'' || a.id AND c.issue_id = a.id WHERE a.status = ''open'' AND a.created_at <= (CAST(strftime(''%s'',''now'') AS INTEGER) - 7200) * 1000 AND c.status = ''superseded'' AND c.last_verdict LIKE ''superseded:closure-observing-probe-at-birth%'' AND upper(trim(c.verify_probe)) LIKE ''SELECT%'' AND c.verify_transport LIKE ''d1-query%'' AND instr(lower(c.verify_probe), ''expected'') > 0 AND instr(lower(c.verify_probe), ''observed'') > 0 AND instr(lower(c.verify_probe), ''agent_issues'') = 0 AND instr(lower(c.verify_probe), ''issue_triage'') = 0 AND instr(lower(c.verify_probe), ''issue_lifecycle'') = 0 AND instr(lower(c.verify_probe), ''close_evidence'') = 0 AND instr(lower(c.verify_probe), ''remediation_contracts'') = 0 AND instr(lower(c.verify_probe), ''remediation_verifications'') = 0 AND instr(c.verify_probe, ''needs-machine'' || ''-probe'') = 0 AND lower(c.verify_probe) NOT LIKE ''%id = '' || a.id || ''%'' AND lower(c.verify_probe) NOT LIKE ''%issue_id = '' || a.id || ''%'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts d WHERE d.issue_id = a.id AND d.status IN (''active'',''holding''))) AS TEXT) AS observed', 'd1-query', 3, 1, 'active', 'PROBE-PLAYBOOKS-1', 'failure-mode detector', 'qnfo-fleet-control', 'failure-mode', datetime('now', '+90 minutes'));

-- ---- the one code lever (a single anchored edit in one file; source qnfo-fleet-control and the BREACH-DOCTOR-1: prefix are on code_merge_trusted_sources)
-- Its closing probe is a code-read of the text the edit adds. The first draft read "no class-C PROBE-NEEDED-1 event in 24 hours", which reads ok on any quiet day: the filer dedupes against an open PN and writes no event
-- (live issue_lifecycle holds a 49-hour class-C gap with the defect present) and is capped at 12 PN per 1440 minutes, so a false pass would have autoclosed the lever and orphaned the code task. Code on main is the defect,
-- so the probe reads main: it fails (missing-marker) while the exclusion is absent and a quiet day cannot pass it. qnfo-cloud-ops PROBE-REVIEW-1 judges d1-query contracts only, so the lever keeps its closing path.
-- On live the INSERT below fires agent_issues_birth_contract_ins, which creates the contract as needs-machine-probe, and contract_probe_templates_loop_merged then parks it as monitoring / probe-template-v2d-loop
-- (source qnfo-fleet-control is a live service_registry row). The UPDATE therefore matches needs-machine-probe, monitoring and superseded alike, and resets the verdict, attempts and due time.
INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control',
  'Charter pillar: autonomy. BREACH-DOCTOR-1 playbook PN-R2 (migrations/2026-10-26-probe-playbooks.sql) closes PROBE-NEEDED-1 issues whose target is an OWNER-TASK or OWNER-NOTE: the target''s definition of done is to act on it or record why not, no table measures that, so no probe can be written for it. It acts only while the PROBE-NEEDED-1 filer is quiet for such targets (control pn-r2-filer-quiet-gate), because rtEnsureLivePath files a PN for every such target without a live contract and the D1 trigger issue_refile_reopen reopens a closed PN within a tick, so a close would flap. 7 class-C PN issues were open on 2026-10-26 and the filer would file for the 11 more such targets that have no live contract and no PN yet (about 57 at the 05:45Z audit).
Doer: the code loop (one edit in one file). Change in qnfo-fleet-control/worker.js, in the string RT_LIVEPATH_ORPHAN_SQL: directly after the line that excludes the PROBE-NEEDED-1: titles (the code-anchor below) add the same exclusion for the owner items, the line + "AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%'' " and nothing else. Bump VERSION by a patch and keep deployed-current.worker.js identical.
Definition of done: RT_LIVEPATH_ORPHAN_SQL on main excludes OWNER-TASK and OWNER-NOTE, that is the text of the code-probe line below is present in qnfo-fleet-control/worker.js. The closing probe is a code-read of main and fails while that text is absent; a quiet day proves nothing, because the filer dedupes against an open PN and writes no event and is capped at 12 PN per 1440 minutes. PN-R2 then closes the class-C PN issues by itself once 1440 minutes pass without a class-C PN event, and its verify (pn-reopened) and the engine''s demotion after 2 failed cases in 24 hours bound a flap.
code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js
code-anchor: AND a.title NOT LIKE ''PROBE-NEEDED-1: issue-%''
code-probe: {"paths": ["qnfo-fleet-control/worker.js"], "contains": "AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%''"}',
  'qnfo-fleet-control', 'autonomy', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title = 'BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control' AND status = 'open');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module)
SELECT 'issue-' || id, id, 'born with the issue (ORPHAN-GUARD-BIRTH-1)', 'needs-machine-probe', 'needs-machine-probe', 'd1-query', 3, 'qnfo-fleet-control', 1, 'needs-machine-probe', 'birth'
FROM agent_issues WHERE title = 'BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control';

UPDATE remediation_contracts SET precondition = 'BREACH-DOCTOR-1 PN-R2: the PROBE-NEEDED-1 filer still files for OWNER-TASK and OWNER-NOTE targets (RT_LIVEPATH_ORPHAN_SQL on main has no exclusion)',
  action = 'the code loop adds the OWNER-TASK and OWNER-NOTE exclusion to RT_LIVEPATH_ORPHAN_SQL in qnfo-fleet-control/worker.js, the stale-PR lane merges it and the canonical deploy ships it; scripts/remediation_consumer.py reads its checkout of main and a pass closes the issue',
  verify_probe = '{"paths": ["qnfo-fleet-control/worker.js"], "contains": "AND a.title NOT LIKE ''OWNER-TASK%'' AND a.title NOT LIKE ''OWNER-NOTE%''"}',
  verify_transport = 'code-read', max_attempts = 1000, expected_cadence_h = 1, status = 'active', module = 'breach-doctor',
  last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime('now')
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title = 'BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control' ORDER BY id DESC LIMIT 1)
  AND status IN ('needs-machine-probe', 'monitoring', 'superseded')
  AND EXISTS (SELECT 1 FROM agent_issues WHERE title = 'BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control' AND status = 'open');

-- ---- DOCTRINE-1 registries
INSERT OR IGNORE INTO control_registry (control, location, kind, guards_against, critical_path, disposition, disposition_state, alternate_path, alternate_tested_at, evidence, issue_id) VALUES
 ('pn-r2-filer-quiet-gate', 'breach_playbooks PN-R2 trigger_sql and action_sql: acts only when no PROBE-NEEDED-1 issue for an OWNER-TASK or OWNER-NOTE target was opened or reopened in the last 24 hours', 'gate',
  'a PN close that the filer undoes: rtEnsureLivePath files a PN for every orphan target and the D1 trigger issue_refile_reopen reopens the closed PN within a tick, so every close would flap', 0, 'replace', 'planned',
  'the code lever (issue BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control) removes the cause in RT_LIVEPATH_ORPHAN_SQL, after which the gate opens by itself 1440 minutes after the last class-C PN event. The lever issue closes only when a code-read of main finds the exclusion, never on a quiet day. A flap is also bounded by verify (pn-reopened) and by the engine demoting a rule after 2 failed cases in 24 hours', NULL,
  'live qnfo-audit 2026-10-26 11:25Z: 7 open PN for OWNER-TASK or OWNER-NOTE targets and 6 PN opened or reopened for such targets in the last 1440 minutes. A gate that releases itself on evidence, not a hold. Expiry: review by 2026-11-02',
  (SELECT id FROM agent_issues WHERE title = 'BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control' ORDER BY id DESC LIMIT 1));

-- beliefs (DOCTRINE-1: a belief a rule acts on gets a belief_registry row and a belief- probe that can falsify it). PN-R2 closes PN issues and PB-T4 installs probes on two beliefs.
INSERT OR IGNORE INTO belief_registry (belief_key, claim, confidence, evidence, probe_class, built_on) VALUES
 ('pn-r2-owner-outcome-unmeasured',
  'No table records whether an OWNER-TASK or OWNER-NOTE was acted on, so no closing probe can measure such an item and a PROBE-NEEDED-1 issue for it cannot be answered with a probe; PN-R2 closes that PN SUPERSEDED BY the item, which stays open.',
  0.8,
  'For: qnfo-audit 2026-10-26 12:15Z: owner_prompts.status read queued for 131 of the 135 closed or wontfix OWNER-TASK issues, so the status is not maintained as an outcome. Against: the other 4 read answered, so the table is sometimes written; whether another table (human_actions, cmd_log) records the outcome of an item was not tested. PN-R2 does not give the open item a doer: 13 of the 21 open owner items had no live contract at 12:15Z and stay listed in v_issue_dead_end and fm-open-issue-no-doer.',
  'belief-pn-r2-owner-outcome-unmeasured', 'PROBE-PLAYBOOKS-1 rule PN-R2; migrations/2026-10-26-probe-playbooks.sql'),
 ('pb-t4-metric-title-is-about-the-metric',
  'An open issue whose title starts with a registered metric_registry key, or is METRIC-TRIGGER-<trigger id>, is about that metric, so a probe that is ok when the metric''s trigger does not hit and has a value (template PB-T4) measures the issue''s definition of done.',
  0.7,
  'For: the T4 hits of 2026-10-26 11:25Z (human_wait_oldest_min, issue 1000000; METRIC-TRIGGER-786, issue 1893) name their metric in the title. Against: a title can start with a metric key and describe another defect (the metric is only where it was noticed); no T4 contract was installed yet at 12:15Z, so no reopen of a T4 issue has been observed (0 reopened events on an issue with a probe-template-v4-metric contract).',
  'belief-pb-t4-metric-title-is-about-the-metric', 'PROBE-PLAYBOOKS-1 rules PB-T4 and PB-T4-green; migrations/2026-10-26-probe-playbooks.sql');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at) VALUES
 ('belief-pn-r2-owner-outcome-unmeasured', NULL,
  'migrations/2026-10-26-probe-playbooks.sql has an ok row in migration_runs and breach_playbooks holds PN-R2',
  'belief probe: falsified means fewer than half of the closed OWNER-TASK issues still read queued in owner_prompts, so the table does record outcomes. Then set belief_registry confidence for pn-r2-owner-outcome-unmeasured to 0 with that count as the evidence, set breach_playbooks PN-R2 to mode measure, and write a probe for owner items from owner_prompts.status instead of closing their PN.',
  'SELECT ''holds'' AS expected, CASE WHEN s.total = 0 THEN ''holds'' WHEN 100.0 * s.q / s.total >= 50 THEN ''holds'' ELSE ''falsified: '' || CAST(ROUND(100.0 * s.q / s.total, 1) AS TEXT) || '' percent of closed OWNER-TASK issues read queued'' END AS observed FROM (SELECT COUNT(*) AS total, COALESCE(SUM(CASE WHEN p.status = ''queued'' THEN 1 ELSE 0 END), 0) AS q FROM agent_issues a JOIN owner_prompts p ON p.issue_id = a.id WHERE a.title LIKE ''OWNER-TASK%'' AND a.status IN (''closed'',''resolved'',''wontfix'')) s',
  'd1-query', 1000, 'qnfo-fleet-control', 1, 'active', 'belief', datetime('now')),
 ('belief-pb-t4-metric-title-is-about-the-metric', NULL,
  'migrations/2026-10-26-probe-playbooks.sql has an ok row in migration_runs and breach_playbooks holds PB-T4',
  'belief probe: above 0 means an issue that carries a PB-T4 template contract (module probe-template-v4-metric) was reopened in the last 10080 minutes, so its title was not about that metric or the metric reads ok while the defect remains. Read the issue, set belief_registry confidence for pb-t4-metric-title-is-about-the-metric to 0 with that issue as the evidence and set breach_playbooks PB-T4 and PB-T4-green to mode measure.',
  'SELECT ''0'' AS expected, CAST((SELECT COUNT(DISTINCT l.issue_id) FROM issue_lifecycle l JOIN remediation_contracts c ON c.issue_id = l.issue_id WHERE l.event = ''reopened'' AND l.ts > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-10080 minutes'') AND c.module = ''probe-template-v4-metric'') AS TEXT) AS observed',
  'd1-query', 1000, 'qnfo-fleet-control', 1, 'active', 'belief', datetime('now'));

INSERT OR IGNORE INTO capability_ledger (capability, provenance, prerequisites, reliability, acquired_at, last_exercised_at, evidence) VALUES
 ('probe-playbooks:repair-closing-paths', 'PROBE-PLAYBOOKS-1 (migrations/2026-10-26-probe-playbooks.sql, rows of breach_playbooks)',
