INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session_01QpQv19uh1padRwZ3u1r766',
  'a closing path the fleet can build from structured facts (ids, counts, enum codes) needs no model and no session, and the doctor engine already validates and bounds a playbook row, so the repair is data: reversible per issue, capped, measured for 30 minutes before it acts',
  'PROBE-PLAYBOOKS-1: 10 breach_playbooks rows (PN-R1, PN-R2, PN-R3, PB-R0, PB-T1, PB-T1-green, PB-T3, PB-T3-green, PB-T4, PB-T4-green), metrics orphan_issues_no_live_path / probe_author_accept_rate_7d / pn_open_over_120m with triggers and a 10-minute refresher, four failure modes with fm- detectors, control pn-r2-filer-quiet-gate, the code lever issue BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control (closing probe: a code-read of the exclusion on main), and the beliefs belief-pn-r2-owner-outcome-unmeasured and belief-pb-t4-metric-title-is-about-the-metric with their belief- probes',
  'qnfo-audit 2026-10-26 11:25Z: 19 open PROBE-NEEDED-1 (4 with a refused contract, 7 for owner items), 75 open issues with no live closing path, 84 with a superseded-at-birth contract; the five PN with a closed target and the six METRIC-UNMEASURED-1 contracts the audit named had been repaired by other loops meanwhile, so those rules start as standing guards with 0 hits',
  'recorded through the canonical path on merge, rows run in measure for 30 minutes and then act; breaches_auto_remediated_24h rises as cases verify',
  'issue_triage close rows of PROBE-NEEDED-1 issues, remediation_contracts rows of class issue-<id> (and the issue''s BACKFILL-1 aliases) bound to one issue per statement, breach_diagnoses, decision_log; no worker, trigger, secret or schedule change',
  'breach_playbooks.enabled = 0 per rule or ops_config breach_doctor = off; every applied case stores its revert_sql in breach_diagnoses; the Rollback header',
  'the doctor repairs the PROBE-NEEDED-1 family and the orphan title families with a known shape, without a model',
  'breaches_auto_remediated_24h >= 6 within 24 h',
  'none', 'breach_playbooks, breach_diagnoses, remediation_contracts, issue_triage, v_journey_state, v_metric_trigger_state, portfolio_gaps; migrations/probe-playbooks.test.mjs'
